<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { qualityApi } from '../api/quality.api'
import type { QualityInspectionPreview, ReasonGroup } from '../models/quality'

const props=defineProps<{visible:boolean;itemId:number;units:number[];productName:string;supplierName:string}>()
const emit=defineEmits<{close:[];success:[]}>()
const operations=[{id:6,label:'缺货补货'},{id:7,label:'缺货不补'},{id:5,label:'退货补货'},{id:3,label:'退货不补'}]
const operation=ref(0),groups=ref<ReasonGroup[]>([]),reasonIds=ref<number[]>([]),preview=ref<QualityInspectionPreview>(),media=ref<string[]>([]),loading=ref(false),uploading=ref(false),submitting=ref(false)
const selectedReasons=computed(()=>groups.value.flatMap(group=>group.reasons).filter(reason=>reasonIds.value.includes(reason.id)))
const canPreview=computed(()=>operation.value>0&&reasonIds.value.length>0&&!loading.value)
watch(()=>props.visible,async visible=>{if(!visible)return;operation.value=0;reasonIds.value=[];preview.value=undefined;media.value=[];if(!groups.value.length){loading.value=true;try{groups.value=await qualityApi.getReasons()}catch(e){uni.showToast({title:e instanceof Error?e.message:'质检问题加载失败',icon:'none'})}finally{loading.value=false}}})
function close(){if(!uploading.value&&!submitting.value)emit('close')}
function toggleReason(id:number){reasonIds.value=reasonIds.value.includes(id)?reasonIds.value.filter(value=>value!==id):[...reasonIds.value,id]}
async function createPreview(){if(!canPreview.value)return;loading.value=true;try{preview.value=await qualityApi.getInspectionPreview(props.itemId,{affectedUnits:props.units,reasonIds:reasonIds.value,operation:operation.value})}catch(e){uni.showToast({title:e instanceof Error?e.message:'处罚信息加载失败',icon:'none'})}finally{loading.value=false}}
async function uploadPaths(paths:string[]){uploading.value=true;try{for(const path of paths)media.value.push((await qualityApi.uploadSupplierItemMedia(props.itemId,path)).url)}catch(e){uni.showToast({title:e instanceof Error?e.message:'凭证上传失败',icon:'none'})}finally{uploading.value=false}}
function addMedia(){const remaining=6-media.value.length;if(remaining<=0)return;uni.showActionSheet({itemList:['拍摄/选择图片','拍摄/选择视频'],success:({tapIndex})=>{if(tapIndex===0)uni.chooseImage({count:remaining,sourceType:['album','camera'],success:r=>uploadPaths(Array.isArray(r.tempFilePaths)?r.tempFilePaths:[r.tempFilePaths])});else uni.chooseVideo({sourceType:['album','camera'],compressed:true,success:r=>uploadPaths([r.tempFilePath])})}})}
async function submit(){if(!preview.value||submitting.value)return;submitting.value=true;try{await qualityApi.inspectSupplierItem(props.itemId,{status:10,affectedUnits:props.units,reasonIds:reasonIds.value,operation:operation.value,evidenceMedia:media.value,allowDowngradeRestock:false});uni.showToast({title:`已标记${props.units.length}扎`,icon:'success'});emit('success')}catch(e){uni.showToast({title:e instanceof Error?e.message:'质检标记失败',icon:'none'})}finally{submitting.value=false}}
</script>

<template><view v-if="visible" class="mask" @click="close"><view class="drawer" @click.stop><view class="handle"/><view class="head"><text @click="close">取消</text><strong>缺货/退货标记</strong><text/></view><scroll-view scroll-y class="content"><view class="object"><strong>{{productName}}</strong><text>本次处理 {{units.length}} 扎</text><small>{{supplierName}}</small></view><template v-if="!preview"><view class="section-title"><strong>处置方式</strong><text>单选</text></view><view class="operations"><view v-for="item in operations" :key="item.id" :class="{active:operation===item.id}" @click="operation=item.id"><text>{{item.label}}</text><i>{{operation===item.id?'✓':''}}</i></view></view><view class="section-title"><strong>质检问题类型</strong><text>可多选</text></view><view v-for="group in groups" :key="group.id" class="reason-group"><text>{{group.name}}</text><view><text v-for="reason in group.reasons" :key="reason.id" :class="{active:reasonIds.includes(reason.id)}" @click="toggleReason(reason.id)">{{reason.name}}</text></view></view></template><template v-else><view class="result"><view><text>处置方式</text><strong>{{operations.find(item=>item.id===operation)?.label}}</strong></view><view><text>问题类型</text><strong>{{selectedReasons.map(item=>item.name).join('、')}}</strong></view></view><view class="penalty"><view><text>供货单价</text><strong>¥{{preview.unitPrice.toFixed(2)}}/扎</strong></view><view><text>涉及货款</text><strong>¥{{preview.principal.toFixed(2)}}</strong></view><view><text>处罚比例</text><strong>{{preview.punishPercent}}%</strong></view><view class="total"><text>本次处罚金额</text><strong>¥{{preview.punishAmount.toFixed(2)}}</strong></view><small>{{preview.formula}}</small></view><view class="section-title"><strong>质检凭证</strong><text>图片/视频共6个</text></view><view class="media"><view v-for="(url,index) in media" :key="url"><text>凭证 {{index+1}}</text><i @click="media.splice(index,1)">×</i></view><view v-if="media.length<6" class="add" @click="addMedia"><strong>＋</strong><text>{{uploading?'上传中':'添加凭证'}}</text></view></view></template></scroll-view><view :class="['actions',{confirming:!!preview}]"><button v-if="preview" class="back" @click="preview=undefined">返回修改</button><button :disabled="preview?submitting:!canPreview" @click="preview?submit():createPreview()">{{preview?(submitting?'提交中…':'确认标记'):(loading?'计算中…':'下一步')}}</button></view></view></view></template>

<style scoped lang="scss">
.mask{position:fixed;z-index:120;inset:0;display:flex;align-items:flex-end;background:rgba(23,43,41,.46)}.drawer{display:flex;width:100%;max-height:90vh;border-radius:28rpx 28rpx 0 0;background:#fff;flex-direction:column}.handle{width:70rpx;height:7rpx;margin:14rpx auto 5rpx;border-radius:7rpx;background:#d7dfdd}.head{display:grid;height:76rpx;align-items:center;padding:0 28rpx;grid-template-columns:1fr 2fr 1fr}.head strong{text-align:center;font-size:27rpx}.head text{color:var(--wms-primary-700);font-size:21rpx}.content{box-sizing:border-box;max-height:65vh;padding:0 28rpx}.object{display:grid;padding:18rpx;border-radius:15rpx;background:var(--wms-background);grid-template-columns:1fr auto}.object strong{font-size:25rpx}.object>text{color:var(--wms-primary-700);font-size:21rpx;font-weight:700}.object small{margin-top:8rpx;color:var(--wms-text-secondary);font-size:18rpx}.section-title{display:flex;align-items:center;justify-content:space-between;margin-top:24rpx}.section-title strong{font-size:23rpx}.section-title text{color:var(--wms-text-secondary);font-size:18rpx}.operations{display:grid;margin-top:12rpx;grid-template-columns:1fr 1fr;gap:10rpx}.operations view{display:flex;height:70rpx;align-items:center;justify-content:space-between;padding:0 15rpx;border:2rpx solid var(--wms-border);border-radius:13rpx}.operations .active{border-color:var(--wms-danger);background:#fff2f0;color:var(--wms-danger);font-weight:700}.operations i{font-style:normal}.reason-group{margin-top:17rpx}.reason-group>text{color:var(--wms-text-secondary);font-size:19rpx}.reason-group>view{display:flex;gap:9rpx;margin-top:9rpx;flex-wrap:wrap}.reason-group>view text{padding:11rpx 15rpx;border-radius:10rpx;background:var(--wms-background);font-size:20rpx}.reason-group>view .active{background:var(--wms-surface-soft);color:var(--wms-primary-700);font-weight:700}.result{margin-top:10rpx}.result>view{display:flex;justify-content:space-between;padding:12rpx 0;border-bottom:1rpx solid var(--wms-border);font-size:21rpx}.result text{color:var(--wms-text-secondary)}.penalty{margin-top:18rpx;padding:16rpx 18rpx;border:1rpx solid #f0d2ce;border-radius:15rpx;background:#fff8f7}.penalty>view{display:flex;justify-content:space-between;padding:8rpx 0;font-size:20rpx}.penalty .total{margin-top:5rpx;padding-top:13rpx;border-top:1rpx solid #efd8d5}.penalty .total strong{color:var(--wms-danger);font-size:28rpx}.penalty small{display:block;margin-top:7rpx;color:var(--wms-text-secondary);font-size:17rpx;text-align:right}.media{display:grid;margin-top:12rpx;grid-template-columns:repeat(3,1fr);gap:10rpx}.media>view{position:relative;display:flex;height:100rpx;align-items:center;justify-content:center;border-radius:12rpx;background:var(--wms-background);font-size:18rpx}.media i{position:absolute;top:4rpx;right:8rpx;font-style:normal}.media .add{border:2rpx dashed var(--wms-border);flex-direction:column}.media .add strong{font-size:29rpx}.actions{display:grid;gap:12rpx;padding:16rpx 28rpx calc(16rpx + env(safe-area-inset-bottom));border-top:1rpx solid var(--wms-border);grid-template-columns:1fr}.actions:has(.back){grid-template-columns:1fr 1.6fr}.actions button{height:78rpx;margin:0;border:0;border-radius:16rpx;background:var(--wms-primary-700);color:#fff;font-size:24rpx;line-height:78rpx}.actions .back{background:var(--wms-background);color:var(--wms-text-primary)}.actions button:after{border:0}.actions button[disabled]{opacity:.45}
</style>
<style scoped>.actions.confirming{grid-template-columns:1fr 1.6fr}</style>
